@startuml

class SensorController {
  + controllerID : string
  + querySensorValues(inhabitantID : string) : float[]
}

class Inhabitant {
  + username : string
  + password : string
}

class Apartment {
  + address : string
  + emailAddress : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorID : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + counterReading : float
}

class SensorValue {
  + timestamp : datetime
  + value : float
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {
  + systemID : string
}

class AdminRights {
  + canConfigure : boolean
}

SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Apartment "1" --> "0..1" EMonitor
Inhabitant "1..*" -- "1" Apartment
Inhabitant "1" --> "1" SensorController
Sensor "1..*" -- "1" Room
Sensor "1" *-- "1" SensorValue
Sensor "1" *-- "1" SensorValue : lastValue
Inhabitant "1" --> "1" AdminRights
AdminRights "1" -- "1" Sensor
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor

@enduml

